import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, Subject } from 'rxjs';
import { Client } from '@stomp/stompjs';
import SockJS from 'sockjs-client';
import {
  ChatMessage,
  ChatRoom,
  FileUploadResponse,
} from '../models/chat.model';

@Injectable({
  providedIn: 'root',
})
export class ChatService {
  private apiUrl = 'http://localhost:8080/api/chat';
  private wsUrl = 'http://localhost:8080/ws-chat';
  private stompClient: Client | null = null;
  private messageSubject = new Subject<ChatMessage>();
  private connected = false;

  constructor(private http: HttpClient) {}

  connect(username: string): Observable<ChatMessage> {
    // Fix: Create socket connection properly
    const socket = new SockJS(this.wsUrl);

    this.stompClient = new Client({
      webSocketFactory: () => socket,
      reconnectDelay: 5000,
      debug: (str) => console.log(str),
    });

    this.stompClient.onConnect = () => {
      console.log('Connected to WebSocket');
      this.connected = true;

      this.stompClient?.subscribe(
        `/user/${username}/queue/messages`,
        (message) => {
          if (message.body) {
            const msg: ChatMessage = JSON.parse(message.body);
            this.messageSubject.next(msg);
          }
        },
      );
    };

    this.stompClient.onStompError = (frame) => {
      console.error('STOMP error:', frame);
    };

    this.stompClient.activate();
    return this.messageSubject.asObservable();
  }

  sendMessage(message: ChatMessage): void {
    if (this.stompClient && this.connected) {
      this.stompClient.publish({
        destination: '/app/send',
        body: JSON.stringify(message),
      });
    } else {
      console.warn('Cannot send message: WebSocket not connected');
    }
  }

  getChatHistory(user1: string, user2: string): Observable<ChatMessage[]> {
    return this.http.get<ChatMessage[]>(
      `${this.apiUrl}/history/${user1}/${user2}`,
    );
  }

  getUnreadCount(username: string): Observable<number> {
    return this.http.get<number>(`${this.apiUrl}/unread/${username}`);
  }

  markAsRead(messageId: number): Observable<void> {
    return this.http.patch<void>(`${this.apiUrl}/read/${messageId}`, {});
  }

  getConversations(username: string): Observable<ChatRoom[]> {
    return this.http.get<ChatRoom[]>(
      `${this.apiUrl}/conversations/${username}`,
    );
  }

  uploadFile(file: File): Observable<FileUploadResponse> {
    const formData = new FormData();
    formData.append('file', file);
    return this.http.post<FileUploadResponse>(
      `${this.apiUrl}/upload`,
      formData,
    );
  }

  getBotResponse(message: string): Observable<ChatMessage> {
    return this.http.post<ChatMessage>(`${this.apiUrl}/bot`, message);
  }

  disconnect(): void {
    if (this.stompClient && this.connected) {
      this.stompClient.deactivate();
      this.connected = false;
    }
  }
}
